    qss = dests(start, 'qs') if qs_left >= 1 and qs > 0 else {}
    sprints = dests(start, 'sprint') if can_move and qs_left >= 1 else {}
    if can_move:
        add_free(start, [('move', start)])
    for q in moves:
        add_free(q, [('move', q)])
    for q in qss:
        add_fixed(q, arrow, [('qs', q)])
