    for q, dr in sprints.items():
        add_fixed(q, dr, [('sprint', q)])
        if wedge:                          # step 3h: the other edge on the anticlockwise side
            add_fixed(q, (dr - 1) % 8, [('sprint', q, (dr - 1) % 8)])
