        add_fixed(q, dr, 1)
    return free, fixed


def _caps(s, side, i):
    """(can_move, quick steps left) for a player now, by the rules' limits."""
    rules = s.ctx.rules
    if s.tokens(side) <= 0:
        return False, 0
