"""Step 3m B7: the goal library becomes labels. Nothing here decides anything: a recogniser names completed sequences
for the review and the trainer, using the GOAL_LIBRARY descriptions as pattern descriptions (goal_library.json:
id, name, conditions). A sequence that created a dilemma or an uncovered threat and matches no label is logged as an
"unnamed action" with its replay (the states before and after).

events: one possession's decisions in order, [(state before, action, state after)].
"""
import json
import os

from . import board as B
from . import rules_config as RC

HERE = os.path.dirname(os.path.abspath(__file__))
LIB = {g['id']: g for g in json.load(open(os.path.join(HERE, 'goal_library.json')))['offence']}


# step 3n G: descriptive labels for patterns the log kept calling unnamed (labels only: they never steer a decision)
EXTRA = {'G1': 'Drive and relocate', 'G2': 'Lift', 'G3': 'Drift', 'G4': 'Empty-side drive'}


def _name(gid):
    return LIB[gid]['name'] if gid in LIB else EXTRA.get(gid, gid)


def _drive(s, b):
    """Is action b (from state s) the ball handler driving: a Dribble, or a movement that gets him closer to the rim?"""
    if b.side != 'O' or b.piece != s.ball:
        return False
    return b.kind == 'dribble' or (b.kind in ('move', 'qs', 'sprint') and B.dist_rim(b.dest) < B.dist_rim(s.o[s.ball]))


def _spacing_labels(events, add):
    """Step 3n G: drive and relocate, lift, drift, empty-side drive."""
    from .decide import lane_squares
    for k, (s, a, n) in enumerate(events):
        if not _drive(s, a):
            continue
        c = s.ball
        cp = a.dest if a.kind != 'dribble' else s.o[c]
        side_of = lambda q: (q[0] > B.W // 2) - (q[0] < B.W // 2)
        mates = [i for i in range(5) if i != c and B.on_board(s.o[i])]
        if mates and all(side_of(s.o[i]) != side_of(cp) or abs(s.o[i][0] - cp[0]) >= 5 for i in mates) and side_of(cp) != 0:
            add('G4', k, k, [c], f'O{c + 1} drives to the empty side')
        # teammates' movement in the same turn group or the offence's next turn
        for m in range(max(0, k - 1), min(len(events), k + 4)):
            s2, b, _ = events[m]
            if m == k or b.side != 'O' or b.piece == c or b.kind not in ('move', 'qs', 'sprint'):
                continue
            i, frm, to = b.piece, s2.o[b.piece], b.dest
            lane = lane_squares(cp, to, 0.5)
            open_line = not any(xp in lane for xp in s2.x)
            if B.zone(to) in ('3', 'L') and open_line and B.cheb(frm, to) >= 1 and B.cheb(to, cp) >= 3:
                add('G1', min(k, m), max(k, m), [c, i], f'O{c + 1} drives and O{i + 1} relocates into his kick-out line')
            if frm[1] <= 3 and to[1] >= frm[1] + 2 and B.zone(to) in ('3', 'L'):
                add('G2', min(k, m), max(k, m), [c, i], f'O{i + 1} lifts out of the corner as O{c + 1} drives')
            if to[1] < frm[1] and to[1] <= 3 and B.zone(to) in ('3', '.') and side_of(to) == side_of(cp):
                add('G3', min(k, m), max(k, m), [c, i], f'O{i + 1} drifts to the corner behind O{c + 1}\'s drive')


def _guard(s, i):
    """The defender nearest attacker i (who is guarding him on this board)."""
    return min(range(5), key=lambda j: (B.cheb(s.x[j], s.o[i]), j))


def _passes(events):
    return [(k, s, a, n) for k, (s, a, n) in enumerate(events) if a.kind == 'pass' and a.side == 'O']


def _caught(events, k):
    """Did the pass at index k arrive (the receiver had the ball afterwards)?"""
    a = events[k][1]
    for s, b, n in events[k + 1:k + 6]:
        if n.stage == 'over' or n.ball == a.target:
            return n.ball == a.target or (n.result is not None and n.result.shooter == a.target)
    return False


def recognise(events):
    """Labels for one possession: [dict(id, label, start, end, who, text)]."""
    out = []

    def add(gid, start, end, who, text):
        out.append(dict(id=gid, label=_name(gid), start=start, end=end, who=who, text=text))
    for k, (s, a, n) in enumerate(events):
        if a.side != 'O':
            continue
        if a.kind == 'screen':
            S = a.piece
            t = B.add(s.o[S], B.DIRS[a.target])
            j = next((j for j, xp in enumerate(s.x) if xp == t or B.adjacent(xp, t)), None)
            ball_d = _guard(s, s.ball)
            for m in range(k + 1, min(len(events), k + 9)):
                s2, b, n2 = events[m]
                if b.side != 'O':
                    continue
                if j == ball_d and b.kind in ('move', 'qs', 'sprint') and b.piece == S and \
                        B.dist_rim(b.dest) < B.dist_rim(s2.o[S]):
                    add('D1', k, m, [S, s.ball], f'O{S + 1} screens X{j + 1} for O{s.ball + 1} and rolls')
                    break
                if j == ball_d and b.kind == 'pass' and b.target == S and B.zone(s2.o[S]) == '3':
                    add('D2', k, m, [S, s.ball], f'O{S + 1} screens for O{s.ball + 1} and pops')
                    break
